namespace RecipeCommunity.Models;

public class Recipe
{
    public int Id { get; set; }
    public string Title { get; set; } = string.Empty;
    public string Category { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
    public List<string> Ingredients { get; set; } = [];
    public List<string> Steps { get; set; } = [];
    public int TotalRatingPoints { get; set; }
    public int RatingCount { get; set; }

    public double AverageRating => RatingCount > 0
        ? Math.Round((double)TotalRatingPoints / RatingCount, 1)
        : 0;
}

namespace RecipeCommunity.Models;

public class RecipeCategory
{
    public string Name { get; set; } = string.Empty;
    public string Icon { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
    public string Slug { get; set; } = string.Empty;
}

using RecipeCommunity.Models;

namespace RecipeCommunity.Services;

public class RecipeService
{
    private readonly List<Recipe> _recipes;
    private int _nextId;

    public RecipeService()
    {
        _recipes = CreateSeedData();
        _nextId = _recipes.Max(r => r.Id) + 1;
    }

    public List<RecipeCategory> GetCategories() =>
    [
        new() { Name = "Breakfast", Slug = "breakfast", Icon = "🥞", Description = "Start your day with delicious morning meals" },
        new() { Name = "Lunch", Slug = "lunch", Icon = "🥗", Description = "Midday meals to keep you energized" },
        new() { Name = "Dinner", Slug = "dinner", Icon = "🍝", Description = "Hearty evening recipes for the whole family" },
        new() { Name = "Desserts", Slug = "desserts", Icon = "🍰", Description = "Sweet treats and indulgent finishes" },
        new() { Name = "Snacks", Slug = "snacks", Icon = "🥨", Description = "Quick bites for any time of day" },
        new() { Name = "Drinks", Slug = "drinks", Icon = "🍹", Description = "Refreshing beverages and cocktails" },
    ];

    public List<Recipe> GetRecipesByCategory(string category) =>
        _recipes.Where(r => r.Category.Equals(category, StringComparison.OrdinalIgnoreCase)).ToList();

    public Recipe? GetRecipeById(int id) =>
        _recipes.FirstOrDefault(r => r.Id == id);

    public void AddRating(int recipeId, int stars)
    {
        var recipe = GetRecipeById(recipeId);
        if (recipe is not null && stars is >= 1 and <= 5)
        {
            recipe.TotalRatingPoints += stars;
            recipe.RatingCount++;
        }
    }

    public void AddRecipe(Recipe recipe)
    {
        recipe.Id = _nextId++;
        _recipes.Add(recipe);
    }

    private static List<Recipe> CreateSeedData() =>
    [
        new()
        {
            Id = 1, Title = "Classic Pancakes", Category = "Breakfast",
            Description = "Fluffy golden pancakes perfect for a lazy weekend morning.",
            Ingredients = ["2 cups flour", "2 eggs", "1½ cups milk", "3 tbsp sugar", "2 tsp baking powder", "¼ tsp salt", "3 tbsp melted butter"],
            Steps = ["Mix dry ingredients in a bowl.", "Whisk eggs, milk, and melted butter together.", "Combine wet and dry ingredients until just blended.", "Pour batter onto a hot greased griddle.", "Flip when bubbles form on the surface.", "Serve with maple syrup and fresh berries."],
            TotalRatingPoints = 18, RatingCount = 4,
        },
        new()
        {
            Id = 2, Title = "Avocado Toast", Category = "Breakfast",
            Description = "Simple, healthy, and endlessly customizable.",
            Ingredients = ["2 slices sourdough bread", "1 ripe avocado", "1 tbsp lemon juice", "Salt and pepper", "Red pepper flakes", "1 egg (optional)"],
            Steps = ["Toast the bread until golden.", "Mash the avocado with lemon juice, salt, and pepper.", "Spread avocado mixture on toast.", "Top with red pepper flakes and a fried egg if desired."],
            TotalRatingPoints = 14, RatingCount = 3,
        },
        new()
        {
            Id = 3, Title = "Caesar Salad", Category = "Lunch",
            Description = "A crisp, creamy classic that never gets old.",
            Ingredients = ["1 head romaine lettuce", "½ cup croutons", "¼ cup parmesan cheese", "3 tbsp Caesar dressing", "1 lemon", "Grilled chicken (optional)"],
            Steps = ["Wash and chop the romaine lettuce.", "Toss lettuce with Caesar dressing.", "Add croutons and shaved parmesan.", "Squeeze lemon over the top.", "Add grilled chicken if desired."],
            TotalRatingPoints = 8, RatingCount = 2,
        },
        new()
        {
            Id = 4, Title = "Grilled Chicken Wrap", Category = "Lunch",
            Description = "A protein-packed wrap that's great on the go.",
            Ingredients = ["2 flour tortillas", "1 grilled chicken breast", "½ cup mixed greens", "¼ cup diced tomatoes", "2 tbsp ranch dressing", "¼ cup shredded cheese"],
            Steps = ["Slice the grilled chicken.", "Warm the tortillas.", "Layer chicken, greens, tomatoes, cheese, and ranch on each tortilla.", "Roll up tightly and slice in half."],
            TotalRatingPoints = 5, RatingCount = 1,
        },
        new()
        {
            Id = 5, Title = "Spaghetti Bolognese", Category = "Dinner",
            Description = "A rich, meaty sauce over perfectly cooked pasta.",
            Ingredients = ["400g spaghetti", "500g ground beef", "1 onion, diced", "3 cloves garlic", "400g crushed tomatoes", "2 tbsp tomato paste", "1 tsp oregano", "Salt and pepper", "Parmesan cheese"],
            Steps = ["Cook spaghetti according to package directions.", "Brown ground beef in a large pan, drain excess fat.", "Sauté onion and garlic until soft.", "Add crushed tomatoes, tomato paste, and oregano.", "Simmer sauce for 20 minutes.", "Serve sauce over spaghetti with parmesan."],
            TotalRatingPoints = 23, RatingCount = 5,
        },
        new()
        {
            Id = 6, Title = "Chicken Stir-Fry", Category = "Dinner",
            Description = "A quick and colorful weeknight dinner.",
            Ingredients = ["2 chicken breasts, sliced", "2 cups mixed vegetables", "3 tbsp soy sauce", "1 tbsp sesame oil", "1 tsp ginger", "2 cloves garlic", "Cooked rice"],
            Steps = ["Cook rice according to package directions.", "Heat sesame oil in a wok over high heat.", "Stir-fry chicken until cooked through.", "Add vegetables, garlic, and ginger.", "Pour in soy sauce and toss to coat.", "Serve over rice."],
            TotalRatingPoints = 12, RatingCount = 3,
        },
        new()
        {
            Id = 7, Title = "Chocolate Chip Cookies", Category = "Desserts",
            Description = "Chewy, gooey cookies with pools of melted chocolate.",
            Ingredients = ["2¼ cups flour", "1 cup butter, softened", "¾ cup sugar", "¾ cup brown sugar", "2 eggs", "1 tsp vanilla extract", "1 tsp baking soda", "2 cups chocolate chips"],
            Steps = ["Preheat oven to 375°F (190°C).", "Cream butter and sugars until fluffy.", "Beat in eggs and vanilla.", "Mix in flour and baking soda.", "Fold in chocolate chips.", "Drop spoonfuls onto baking sheets.", "Bake for 9-11 minutes until golden."],
            TotalRatingPoints = 20, RatingCount = 4,
        },
        new()
        {
            Id = 8, Title = "Trail Mix", Category = "Snacks",
            Description = "A customizable mix of nuts, seeds, and dried fruit.",
            Ingredients = ["1 cup almonds", "1 cup cashews", "½ cup dried cranberries", "½ cup raisins", "½ cup chocolate chips", "½ cup sunflower seeds"],
            Steps = ["Combine all ingredients in a large bowl.", "Toss to mix evenly.", "Store in an airtight container."],
            TotalRatingPoints = 7, RatingCount = 2,
        },
        new()
        {
            Id = 9, Title = "Mango Smoothie", Category = "Drinks",
            Description = "A tropical, refreshing blend of mango and yogurt.",
            Ingredients = ["1 cup frozen mango chunks", "1 banana", "½ cup Greek yogurt", "1 cup orange juice", "1 tbsp honey"],
            Steps = ["Add all ingredients to a blender.", "Blend until smooth.", "Pour into a glass and serve immediately."],
            TotalRatingPoints = 9, RatingCount = 2,
        },
    ];
}

