else
{
    <EditForm Model="_recipe" OnValidSubmit="HandleSubmit" FormName="submitRecipe">
        <DataAnnotationsValidator />

        <div class="mb-3">
            <label class="form-label" for="title">Recipe Title</label>
            <InputText id="title" class="form-control" @bind-Value="_recipe.Title" placeholder="e.g., Grandma's Apple Pie" required />
        </div>

        <div class="mb-3">
            <label class="form-label" for="category">Category</label>
            <InputSelect id="category" class="form-select" @bind-Value="_recipe.Category" required>
                <option value="">-- Select a category --</option>
                @foreach (var cat in RecipeService.GetCategories())
                {
                    <option value="@cat.Name">@cat.Icon @cat.Name</option>
                }
            </InputSelect>
        </div>

        <div class="mb-3">
            <label class="form-label" for="description">Short Description</label>
            <InputText id="description" class="form-control" @bind-Value="_recipe.Description" placeholder="A brief description of your recipe" required />
        </div>

        <div class="mb-3">
            <label class="form-label">Ingredients <small class="text-muted">(one per line)</small></label>
            <InputTextArea class="form-control" rows="6" @bind-Value="_ingredientsText" placeholder="2 cups flour&#10;1 cup sugar&#10;3 eggs" required />
        </div>

        <div class="mb-3">
            <label class="form-label">Steps <small class="text-muted">(one per line)</small></label>
            <InputTextArea class="form-control" rows="6" @bind-Value="_stepsText" placeholder="Preheat oven to 350°F.&#10;Mix dry ingredients.&#10;Bake for 30 minutes." required />
        </div>

        <button type="submit" class="btn btn-primary" disabled="@(!IsFormValid)">Submit Recipe</button>
        <a href="/" class="btn btn-outline-secondary ms-2">Cancel</a>
    </EditForm>
}

@code {
    [Inject] public required RecipeService RecipeService { get; set; }

    private Recipe _recipe = new();
    private string _ingredientsText = string.Empty;
    private string _stepsText = string.Empty;
    private bool _submitted;

    private bool IsFormValid =>
        !string.IsNullOrWhiteSpace(_recipe.Title)
        && !string.IsNullOrWhiteSpace(_recipe.Category)
        && !string.IsNullOrWhiteSpace(_recipe.Description)
        && !string.IsNullOrWhiteSpace(_ingredientsText)
        && !string.IsNullOrWhiteSpace(_stepsText);

    private void HandleSubmit()
    {
        _recipe.Ingredients = _ingredientsText
            .Split('\n', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries)
            .ToList();
        _recipe.Steps = _stepsText
            .Split('\n', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries)
            .ToList();

        RecipeService.AddRecipe(_recipe);
        _submitted = true;
    }

    private void ResetForm()
    {
        _recipe = new Recipe();
        _ingredientsText = string.Empty;
        _stepsText = string.Empty;
        _submitted = false;
    }
}

@rendermode InteractiveServer

<div class="star-rating">
    @for (int i = 1; i <= 5; i++)
    {
        var star = i;
        <span class="star @(star <= (_hovered ?? _selected) ? "filled" : "")"
              @onclick="() => SelectStar(star)"
              @onmouseover="() => _hovered = star"
              @onmouseout="() => _hovered = null"
              role="button"
              title="@star star(s)">★</span>
    }
    @if (_submitted)
    {
        <span class="rating-thanks">Thanks for rating!</span>
    }
</div>

@code {
    [Parameter] public int RecipeId { get; set; }
    [Parameter] public double AverageRating { get; set; }
    [Parameter] public int RatingCount { get; set; }
    [Parameter] public EventCallback<int> OnRate { get; set; }

    private int _selected;
    private int? _hovered;
    private bool _submitted;

    protected override void OnParametersSet()
    {
        _selected = (int)Math.Round(AverageRating);
    }

    private async Task SelectStar(int star)
    {
        _selected = star;
        _submitted = true;
        await OnRate.InvokeAsync(star);
    }
}

