@page "/category/{Slug}"
@using RecipeCommunity.Models
@using RecipeCommunity.Services

<PageTitle>@(_category?.Name ?? "Category") — Recipe Community</PageTitle>

@if (_category is null)
{
    <h2>Category not found</h2>
    <p><a href="/">Back to Home</a></p>
}
else
{
    <h1>@_category.Icon @_category.Name</h1>
    <p class="lead">@_category.Description</p>

    @if (_recipes.Count == 0)
    {
        <div class="alert alert-info">No recipes in this category yet. <a href="submit">Be the first to submit one!</a></div>
    }
    else
    {
        <div class="row">
            @foreach (var recipe in _recipes)
            {
                <div class="col-md-6 mb-4">
                    <div class="card h-100 shadow-sm">
                        <div class="card-body">
                            <h5 class="card-title">@recipe.Title</h5>
                            <p class="card-text">@recipe.Description</p>
                            <div class="mb-2">
                                <span class="text-warning">@(new string('★', (int)Math.Round(recipe.AverageRating)))@(new string('☆', 5 - (int)Math.Round(recipe.AverageRating)))</span>
                                <small class="text-muted">(@recipe.RatingCount ratings)</small>
                            </div>
                            <a href="recipe/@recipe.Id" class="btn btn-primary btn-sm">View Recipe</a>
                        </div>
                    </div>
                </div>
            }
        </div>
    }
}

@code {
    [Parameter] public string Slug { get; set; } = string.Empty;
    [Inject] public required RecipeService RecipeService { get; set; }

    private RecipeCategory? _category;
    private List<Recipe> _recipes = [];

    protected override void OnParametersSet()
    {
        _category = RecipeService.GetCategories()
            .FirstOrDefault(c => c.Slug.Equals(Slug, StringComparison.OrdinalIgnoreCase));

        _recipes = _category is not null
            ? RecipeService.GetRecipesByCategory(_category.Name)
            : [];
    }
}

