.form-floating > .form-control-plaintext:focus::placeholder, .form-floating > .form-control:focus::placeholder {
    text-align: start;
}

/* Star rating widget */
.star-rating {
    display: inline-flex;
    align-items: center;
    gap: 2px;
}

.star-rating .star {
    font-size: 2rem;
    color: #ccc;
    cursor: pointer;
    transition: color 0.15s, transform 0.15s;
    user-select: none;
}

.star-rating .star:hover {
    transform: scale(1.2);
}

.star-rating .star.filled {
    color: #ffc107;
}

.star-rating .rating-thanks {
    margin-left: 0.75rem;
    color: #28a745;
    font-weight: 500;
}

